  // ── update con conflicto (412) ────────────────────────────────────────────

  describe('update with original (412 conflict)', () => {
    const URL = 'http://test/items';
    const original = { id: '1', name: 'Original' };
    const sent = { id: '1', name: 'Mine' };
    const current = { id: '1', name: 'Theirs' };
    let http: HttpTestingController;

    /** Proveedor sobre HttpClient para probar las respuestas HTTP reales. */
    function httpProvider(): RepositoryProvider<Item, any> {
      const client = TestBed.inject(HttpClient);
      return buildProvider({
        update: (key: string, item: Item) => client.put<Item>(`${URL}/${key}`, item),
        retrieve: (key: string) => client.get<Item>(`${URL}/${key}`),
      });
    }

    beforeEach(() => {
      TestBed.configureTestingModule({ providers: [provideHttpClient(), provideHttpClientTesting()] });
      http = TestBed.inject(HttpTestingController);
    });

    afterEach(() => http.verify());

    it('takes the current value from the error body and marks the 412 as handled', () => {
      const repo = buildRepo(httpProvider());
      let error: unknown;
      repo.update(sent, { original }).subscribe({ error: (err) => (error = err) });

      const put = http.expectOne(`${URL}/1`);
      put.flush(current, { status: 412, statusText: 'Precondition Failed' });

      expect(isEditConflict(error)).toBeTrue();
      const conflict = (error as EditConflictError<Item>).conflict;
      expect(conflict).toEqual({ original, sent, current });
      const cause = (error as EditConflictError<Item>).cause as HttpErrorResponse;
      expect(cause.status).toBe(412);
    });

    it('re-reads the current value skipping the cache when the body is empty', () => {
      const repo = buildRepo(httpProvider());
      // Deja el valor original en caché: la relectura no debe usarlo
      repo.add(original).subscribe();
      let error: unknown;
      repo.update(sent, { original }).subscribe({ error: (err) => (error = err) });

      http
        .expectOne({ method: 'PUT', url: `${URL}/1` })
        .flush(null, { status: 412, statusText: 'Precondition Failed' });
      http.expectOne({ method: 'GET', url: `${URL}/1` }).flush(current);

      expect((error as EditConflictError<Item>).conflict.current).toEqual(current);
      let retrieved: Item | undefined;
      repo.retrieve('1').subscribe((value) => (retrieved = value));
      http.expectNone(`${URL}/1`);
      expect(retrieved).toEqual(current);
    });

    it('propagates the re-read error instead of a conflict', () => {
      const repo = buildRepo(httpProvider());
      let error: unknown;
      repo.update(sent, { original }).subscribe({ error: (err) => (error = err) });

      http
        .expectOne({ method: 'PUT', url: `${URL}/1` })
        .flush(null, { status: 412, statusText: 'Precondition Failed' });
      http.expectOne({ method: 'GET', url: `${URL}/1` }).flush(null, { status: 404, statusText: 'Not Found' });

      expect(isEditConflict(error)).toBeFalse();
      expect((error as HttpErrorResponse).status).toBe(404);
    });

    it('lets other errors through untouched', () => {
      const repo = buildRepo(httpProvider());
      let error: unknown;
      repo.update(sent, { original }).subscribe({ error: (err) => (error = err) });

      http.expectOne(`${URL}/1`).flush(null, { status: 500, statusText: 'Server Error' });

      expect((error as HttpErrorResponse).status).toBe(500);
    });

    it('does not handle the 412 without original', () => {
      const repo = buildRepo(httpProvider());
      let error: unknown;
      repo.update(sent).subscribe({ error: (err) => (error = err) });

      http.expectOne(`${URL}/1`).flush(current, { status: 412, statusText: 'Precondition Failed' });

      expect(isEditConflict(error)).toBeFalse();
      expect((error as HttpErrorResponse).status).toBe(412);
    });
  });

